-- ============================================================================
--  SiGeRU 2026 - Datos de prueba
--  Archivo: datos_prueba.sql
--  Que es : datos de ejemplo para poder mostrar el sistema funcionando.
--  Requiere: haber importado antes schema.sql
--
--  Los datos son de Montevideo y verosimiles a proposito (direcciones reales,
--  matriculas con formato uruguayo, horarios de recoleccion plausibles): en la
--  defensa se ve el sistema con datos que parecen de produccion y no con
--  "prueba1 / prueba2".
--
--  Todos los usuarios tienen la contrasena sigeru2026, guardada como hash bcrypt.
-- ============================================================================

--  SEED DE DEFENSA (generado por generadores/importar_contenedores_intendencia.py a partir de datos_prueba.sql; NO editar a mano).
--  Contenedores reales de la Intendencia de Montevideo: datos abiertos, Licencia de DAG de Uruguay (ver fuentes-intendencia/LEEME.md).
--  Es una MUESTRA para la demostracion: 100 contenedores por municipio y 5 rutas de 20. Carga con herramientas/xampp/restaurar-base-defensa.cmd.
-- ============================================================================

USE sigeru;

-- Se vacia todo antes de cargar, para poder reimportar cuantas veces haga falta.
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE limite_peticion;
TRUNCATE TABLE auditoria;
TRUNCATE TABLE historial_incidencia;
TRUNCATE TABLE incidencia;
TRUNCATE TABLE notificacion;
TRUNCATE TABLE historial_maquinaria;
TRUNCATE TABLE movimiento_stock;
TRUNCATE TABLE recepcion;
TRUNCATE TABLE vaciado;
TRUNCATE TABLE recoleccion;
TRUNCATE TABLE ruta_contenedor;
TRUNCATE TABLE ruta;
TRUNCATE TABLE maquinaria;
TRUNCATE TABLE camion;
TRUNCATE TABLE estado_contenedor;
TRUNCATE TABLE contenedor;
TRUNCATE TABLE usuario;
TRUNCATE TABLE solicitud_registro;
TRUNCATE TABLE cuadrilla;
TRUNCATE TABLE tipo_residuo;
TRUNCATE TABLE zona;
TRUNCATE TABLE centro_acopio;
TRUNCATE TABLE rol;
SET FOREIGN_KEY_CHECKS = 1;


-- --- 1) Roles ---------------------------------------------------------------


-- --- 2) Centros de acopio ---------------------------------------------------


-- --- 3) Zonas ---------------------------------------------------------------
-- DEFENSA: la zona es el MUNICIPIO (A, B, C, CH, D, E, F, G), no el barrio. Fuente de los datos: ver el LEEME de fuentes-intendencia.


-- --- 4) Tipos de residuo ----------------------------------------------------


-- --- 5) Cuadrillas ----------------------------------------------------------
-- DEFENSA: una cuadrilla por municipio, cada una con el suyo (migracion 020; los ids de las zonas 1 a 8 son los mismos que los de las cuadrillas).
-- Todas matutinas: las 40 rutas de este seed salen entre las 06:00 y las 09:30, y la sugerencia de «Asignacion» avisa cuando el turno no coincide con la hora.


-- --- 6) Solicitudes de registro ---------------------------------------------
-- Dos ya resueltas (una aprobada, que origino un usuario) y dos pendientes,
-- para que la pantalla de aprobacion tenga algo que mostrar.


-- --- 7) Usuarios ------------------------------------------------------------
-- Contrasena de todos: sigeru2026


-- El Operario trabaja en un centro (extras, parte 12): Sergio Ferreira, en el Felipe Cardoso.
UPDATE usuario SET id_centro = 1 WHERE id_usuario = 4;

-- Cedulas de prueba (ficticias, con digito verificador valido): las cuadrillas inician sesion con cedula y contrasena (migracion 022).
UPDATE usuario SET cedula = CASE id_usuario WHEN 2 THEN '41000019' WHEN 5 THEN '41000025' END WHERE id_usuario IN (2, 5);

-- DEFENSA: un usuario de prueba por cada cuadrilla que no tenia (clave de todos: sigeru2026). Fictizios.

-- Cedulas de prueba (ficticias, con digito verificador valido): las cuadrillas inician sesion con cedula y contrasena (migracion 022).
UPDATE usuario SET cedula = CASE id_usuario WHEN 7 THEN '41000031' WHEN 8 THEN '41000047' WHEN 9 THEN '41000053'
    WHEN 10 THEN '41000069' WHEN 11 THEN '41000075' WHEN 12 THEN '41000081' END WHERE id_usuario IN (7, 8, 9, 10, 11, 12);



-- --- 8) Contenedores --------------------------------------------------------
-- DEFENSA: 800 contenedores REALES de la Intendencia de Montevideo (100 por municipio) mas el CNT-010 retirado del seed de pruebas.
-- Los CNT-001 a CNT-010 conservan codigo, estado y tipo del seed de pruebas y toman la ubicacion real mas cercana a la original.
-- Los 'lleno' de los MVD-* son DATOS DE DEMOSTRACION. Capacidad vacia: la fuente no la trae y no se inventa.


-- --- 9) Historial de estados de contenedor ----------------------------------
-- Muestra la trazabilidad: el CNT-005 se rompio y paso a mantenimiento, el
-- CNT-010 se dio de baja despues de reparaciones repetidas.


-- DEFENSA: historial de los contenedores 'lleno' de demostracion.


-- --- 10) Camiones -----------------------------------------------------------


-- DEFENSA: camiones operativos de mas, para poder asignar varias rutas a la vez.


-- --- 11) Maquinaria de los centros de acopio --------------------------------
-- Lo que la letra llama "maquinaria basica en vertederos y centros de acopio".
-- Hay al menos una maquina por centro y los tres estados representados, para
-- que el filtro de la pantalla tenga algo que filtrar.


-- --- 12) Rutas --------------------------------------------------------------
-- DEFENSA: 40 rutas predefinidas, 5 por municipio, de 20 contenedores cada una (la ruta N de un municipio sale el dia N de la semana).

-- Los contenedores de cada ruta, en orden de visita. El CNT-005 esta en mantenimiento: sigue en su ruta y se muestra como 'no se recolecta'.

